  let grounded = 0;
  for (const it of items) {
    const problems = [];
    const ids = [...new Set([...(it.text.match(/\bT\d{3}\b/g) ?? []), ...(it.task_ids ?? [])])];
    const outOfScope = ids.filter((id) => !allowed.ids.has(id));
